const fs = require('fs');
const path = require('path');

const root = __dirname;
const manifestName = 'backup-manifest.json';

function collect(dir, results) {
  for (const entry of fs.readdirSync(dir, { withFileTypes: true })) {
    if (entry.name.startsWith('.')) continue;
    const full = path.join(dir, entry.name);
    if (entry.isDirectory()) {
      collect(full, results);
    } else if (entry.isFile()) {
      const rel = path.relative(root, full).split(path.sep).join('/');
      if (rel !== manifestName) results.push(rel);
    }
  }
}

const files = [];
collect(root, files);
files.sort();

fs.writeFileSync(
  path.join(root, manifestName),
  JSON.stringify({ files }, null, 2) + '\n'
);

console.log(`Wrote ${manifestName} with ${files.length} file(s).`);

